   "body": "自從西元 2020 年初嚴重特殊傳染性肺炎（COVID-19）疫情爆發後，迅速在全球蔓延，犯罪型態也因為疫情升溫而產生明顯的變化，雖然不同國家因其國情在疫情期間犯罪變化不盡相同，但以下現象普遍出現在因疫情而封城（lockdown）的國家：搶劫、竊盜大幅下降，家暴、網路犯罪飆升。請以一般化緊張理論和日常生活理論解釋此現象。（25 分）",
