   "body": "二、警察在例行巡邏時，發現前科累累，甫出獄的張三神情可疑地在雜貨店\n  門口張頭探腦，於是向前盤查，因而發現其攜帶有槍枝，並以現行犯逮\n  捕張三。逮捕後，警察搜索張三隨身攜帶的背包，發現有毒品。請問，\n  警察所發現的槍枝及毒品，有無證據能力？應如何判斷？（25 分）",
