   "body": "一、黑道份子甲因涉嫌刑案遭起訴，為避免關鍵證人乙出庭作證對其不利之\n  內容，甲乃將乙在就讀小學之兒子A 擄走拘禁，並威脅乙在法庭上必須\n  為對其有利之陳述，否則A 將會有生命危險。之後，乙因恐懼兒子遇害，\n  遂於法庭上具結後作證時，說謊陳述對甲有利的關鍵事實。事後，甲隨即\n  將A 釋放，A 毫髮無傷。試討論本案中甲、乙可能應負之刑責？（25 分）",
