   "body": "二、甲深夜潛入A 之住宅，在竊得若干財物後，發現屋主之女兒B 正在熟\n  睡，竟起色心對B 上下其手撫摸其身體，B 因熟睡全然未覺。數分鐘後，\n   A 起床上廁所時撞見甲之惡行，甲情急之下將竊得財物丟棄逃逸，同時\n  擺出空手道架式警告A 不可追來、否則將對其不利，A 雖不怕、但心想\n  並無財物損失、不願與其糾纏，遂放任甲離去。請討論甲之行為應如何\n  論罪？（25 分）",
