   "body": "三、甲涉犯槍砲彈藥刀械管制條例罪嫌，司法警察乙於115 年5 月5 日23 點\n    20 分持法官所簽發之搜索票，前往甲宅執行搜索，經乙出示證件及搜索\n  票並詢問甲是否同意進行夜間搜索，甲沉默不語，乙即進入甲宅搜索，\n  扣得槍枝一把。請詳附理由說明該扣得槍枝是否具有證據能力？（25 分）",
