   "body": "四、國小畢業之年邁老翁甲涉犯洗錢防制法第22 條第3 項第1 款罪嫌（收\n  受對價提供帳戶於他人使用），經檢察官向管轄法院提起公訴，審理期間\n  檢察官提出證人乙、丙之警詢筆錄及檢訊筆錄於法庭，被告甲於證據調\n  查時表示「無意見」，法院遽認被告甲於審判程序同意作為證據，並依此\n  等證據諭知有罪判決。請詳附理由說明法院依據被告甲表示「無意見」\n  之證據為有罪判決是否合法？（25 分）",
