   "body": "二、車禍經常引來人群駐足圍觀，警察就近初步了解車禍發生時，目擊者的\n  見聞。但目擊者們對於事發現場的說詞往往各有自己的版本，讓人難以\n  置信他們是在同一現場。這牽涉到人的記憶。\n  ㈠請詳述記憶提取的心理歷程。（10 分）\n  ㈡請列出至少五個影響現場目擊者證詞正確性的因素，並詳加說明。（15 分）",
