   "body": "一、古典學派犯罪學者邊沁（Bentham）說，「人因為愛財富，愛擁有很多東\n  西，帶來犯罪動機。」社會解組理論學者派克（Park）強調，達爾文進\n   化論（Darwinian evolution）左右都市環境區位生態，亦帶來犯罪問題；\n  社會控制理論學者赫胥（Hirschi）相信，所有的人皆有犯罪本能。因此，\n  犯罪學者研究的問題應該是：「為什麼人不犯罪？」。試從人性角度詮釋\n  如何影響犯罪學古典學派、社會解組理論、緊張理論，以及社會控制理\n   論。（25 分）",
