   "body": "四、全球的趨勢似乎是將酒後駕車犯罪化，且加重對於酒後駕駛以及因而肇\n  事者的處罰，我國也在1999 年將酒後不能安全駕駛罪納入公共危險罪\n   章規範。首先，請分別從無被害者犯罪（Victimless Crime）以及問題行\n   為症候群（Problem Behavior Syndrome）等概念探討與剖析酒後駕駛（無\n  肇事）行為。其次，請從嚇阻理論的觀點討論及列舉嚴格的立法與執法\n  可能奏效的原因及其副作用。（25 分）",
