   "body": "四、環境犯罪學興起，使得傳統犯罪學強調的犯罪原因探究，逐漸轉移至對\n  情境與環境的理解，因而影響近代的犯罪預防學理。環境犯罪學強調犯\n  罪機會是犯罪發生的根本原因之一，請就Clarke 與Felson 的犯罪機會十\n  大原則加以說明，並說明以環境犯罪學所影響的情境犯罪預防模式內\n  涵，及設計情境犯罪預防模式來防範超商暴力。（25 分）",
   "sourceUrl": "https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=505&code=112070&q=1&s=1410&t=Q",
