   "body": "一、Akers 在1970 年代發展差別增強理論（differential reinforcement theory），\n   此理論修正Sutherland 的差別接觸理論、融入Skinner 的操作制約與\n    Bandura 的社會學習理論。該理論引述操作制約觀點，認為人們學習社\n  會行為會受其結果所影響，行為因受到獎賞或避免懲罰而受到增強，它\n  也認為犯罪行為是透過學習而來的，其核心在於行為受到增強（獎賞）\n  或懲罰的結果。差別增強理論主要包含四個元素概念來解釋行為如何被\n  選擇與持續，請說明這四個元素概念與主張。（25 分）",
