   "body": "三、個案情境：「一位太太正和諮商師/助人者談論她正在調適由先生提出的\n  離婚協議。她形容自己是個脾氣好、柔順守節、全心照護家人的賢妻良\n  母，但對先生為何會提出離婚表示相當驚訝與困惑。在第三次的晤談\n  中，她告訴諮商師/助人者：『我在與先生結婚後不久曾有過一次外遇，\n  但該事件之後我深感愧疚，並極力彌補我先生，為何他還要跟我離婚\n   呢？』」請針對上述情境運用同理心（empathy）與面質（confrontation）\n  的技術論述可能的反應語句？另請說明面質技術的概念，以及其使用時\n  機為何？（25 分）",
