   "body": "民國 112 年 6 月 21 日總統公布施行少年事件處理法修正，其中為落實憲法第 8 條對人身自由之保障，及司法院釋字第 664 號解釋所揭示本法係為維護少年健全自我成長所設置之特殊保護制度，暨兒童權利公約第40 條關於少年司法之正當法律程序要求，對少年之同行、搜索及扣押等強制處分程序，及執行時得否對少年使用約束工具等，即有依少年保護優先原則而有別於成人刑事司法程序設計之必要。請說明目前少年事件處理法第 18 條之 8 當中對少年行使強制處分等程序時身體權、名譽權注意事項以及使用、限制使用約束工具之規定。（25 分）",
